using System.Buffers.Binary;
using System.IO.Compression;
using System.Text;
using PdfObjectKit;
using PdfObjectKit.Editors;
using static PdfObjectKit.PdfPrimitives;

internal static class ImageInsertionTests
{
    // 2x1 JPEG generated by Windows' independent image encoder.
    private const string Jpeg = "";

    public static void Run()
    {
        var checks = 0;
        void Check(bool condition, string name)
        {
            if (!condition)
            {
                throw new Exception("Image insertion: " + name);
            }

            checks++;
        }

        PdfObjectDocument Fixture()
        {
            return PdfReader.Read(PdfFixture.Create(null, new("Original"), new("Original")));
        }

        var jpeg = Convert.FromBase64String(Jpeg);
        var document = Fixture();
        document.TextIndex[0].Runs![0].Text = "Changed";
        var id = PdfImageEditor.InsertImage(document, 1, jpeg, 50, 60, 200, 100);
        Check(document.TextIndex[0].Text == "Original", "index text edit ignored");
        Check(document.TextIndex[1].Text == "Original", "other page text preserved");
        Check(document.TextIndex[0].Runs is null && document.TextIndex[0].RunWarning is not null, "index refreshed for multiple streams");
        var image = document.Objects.Single(o => o.Id == id).Value;
        Check(image.Entries!["Filter"].Name == "DCTDecode" && Convert.FromBase64String(image.Base64!).SequenceEqual(jpeg), "JPEG program retained");
        Check(image.Entries["Width"].Number == "2" && image.Entries["Height"].Number == "1", "JPEG dimensions read");
        var occurrence = document.ImageIndex[0].Images.Single();
        Check(occurrence.ImageObjects.Single() == id, "image index reference");
        Check(occurrence.Corners.SequenceEqual(new[] { new PdfImagePoint(50, 60), new PdfImagePoint(250, 60), new PdfImagePoint(250, 160), new PdfImagePoint(50, 160) }), "display rectangle");
        Check(document.ImageIndex[1].Images.Count == 0, "other page unchanged");
        var pdf = PdfWriter.Write(PdfConverter.FromJson(PdfConverter.ToJson(document)));
        Check(PdfReader.Read(pdf).ImageIndex[0].Images.Single().ImageObjects.Single() == id, "JSON/PDF round trip");
        using (var independent = PdfSharp.Pdf.IO.PdfReader.Open(new MemoryStream(pdf), PdfSharp.Pdf.IO.PdfDocumentOpenMode.Import))
        {
            var resources = independent.Pages[0].Resources.Elements.GetDictionary("/XObject")!;
            var inserted = resources.Elements.GetDictionary("/PdfObjectKitImage")!;
            Check(inserted.Elements.GetInteger("/Width") == 2 && inserted.Elements.GetName("/Filter") == "/DCTDecode", "independent reader sees JPEG image");
        }

        var second = PdfImageEditor.InsertImage(document, 1, jpeg, -10, 20, 10, 20);
        Check(second != id && document.ImageIndex[0].Images.Count == 2, "repeat insertion with unique name");
        Check(document.ImageIndex[0].Images[0].Corners[0] == new PdfImagePoint(50, 60), "previous placement preserved");

        // Shared content and inherited, indirect resources must not be edited in place.
        document = Fixture();
        var graph = new PdfGraph(document);
        var pages = graph.Pages();
        var oldStream = pages[0].Streams.Single();
        oldStream.Value.Base64 = Convert.ToBase64String(Encoding.ASCII.GetBytes("2 0 0 2 5 6 cm 0 0 1 1 re W n\n" + Encoding.ASCII.GetString(Convert.FromBase64String(oldStream.Value.Base64!))));
        var oldData = oldStream.Value.Base64;
        var resourcesId = new PdfReference(document.Objects.Max(o => o.Id.ObjectNumber) + 1);
        var xobjectsId = new PdfReference(resourcesId.ObjectNumber + 1);
        var unusedImageId = new PdfReference(resourcesId.ObjectNumber + 2);
        var sharedResources = pages[0].Resources;
        sharedResources.Entries!["XObject"] = Ref(xobjectsId);
        document.Objects.Add(new(resourcesId, sharedResources));
        document.Objects.Add(new(xobjectsId, Dict(("PdfObjectKitImage", Ref(unusedImageId)))));
        document.Objects.Add(new(unusedImageId, image));
        var parent = graph.Resolve(pages[0].Dictionary.Entries!["Parent"]);
        parent.Entries!["Resources"] = Ref(resourcesId);
        foreach (var page in pages)
        {
            page.Dictionary.Entries!.Remove("Resources");
            page.Dictionary.Entries["Contents"] = Ref(oldStream.Id);
        }

        document.TextIndex.Clear();
        PdfImageEditor.InsertImage(document, 1, jpeg, 20, 30, 40, 50);
        graph = new PdfGraph(document);
        pages = graph.Pages();
        Check(graph.Resolve(Ref(oldStream.Id)).Base64 == oldData, "shared original stream unchanged");
        Check(!pages[1].Dictionary.Entries!.ContainsKey("Resources") && pages[1].Streams.Single().Id == oldStream.Id, "other page still inherits resources and shared stream");
        Check(graph.Resolve(Ref(xobjectsId)).Entries!.Count == 1, "shared XObject dictionary unchanged");
        Check(graph.Get(pages[0].Resources, "XObject")!.Entries!.ContainsKey("PdfObjectKitImage1"), "resource name collision handled");
        Check(document.ImageIndex[0].Images.Single().Corners[0] == new PdfImagePoint(20, 30), "existing transform isolated");
        var content = Encoding.ASCII.GetString(Convert.FromBase64String(pages[0].Streams[^1].Value.Base64!));
        Check(content.StartsWith("\nQ\nn\nq\n"), "graphics restore precedes image drawing");

        // PNG filters 0..4, RGB, grayscale, alpha, and palette transparency.
        for (byte filter = 0; filter <= 4; filter++)
        {
            var rgb = new byte[] { 255, 0, 0, 0, 0, 255, 20, 30, 40, 50, 60, 70 };
            document = Fixture();
            id = PdfImageEditor.InsertImage(document, 2, Png(2, 2, 2, rgb, filter), 1, 2, 3, 4);
            image = document.Objects.Single(o => o.Id == id).Value;
            Check(Inflate(image).SequenceEqual(rgb), "PNG filter " + filter);
            Check(!image.Entries!.ContainsKey("SMask"), "opaque PNG has no soft mask");
        }

        document = Fixture();
        id = PdfImageEditor.InsertImage(document, 1, Png(3, 2, 0, [0x40, 0xA0], 0, transparency: [0, 1], bitDepth: 1), 0, 0, 30, 20);
        image = document.Objects.Single(o => o.Id == id).Value;
        Check(Inflate(image).SequenceEqual(new byte[] { 0, 255, 0, 255, 0, 255 }), "1-bit grayscale PNG row padding");
        Check(Inflate(new PdfGraph(document).Resolve(image.Entries!["SMask"])).SequenceEqual(new byte[] { 255, 0, 255, 0, 255, 0 }), "1-bit grayscale transparency");

        foreach (var color in new byte[] { 0, 3, 4, 6 })
        {
            var samples = color switch { 0 => new byte[] { 0, 200 }, 3 => [0, 1], 4 => [0, 255, 200, 50], _ => [255, 0, 0, 255, 0, 0, 255, 50] };
            var palette = color == 3 ? new byte[] { 255, 0, 0, 0, 0, 255 } : null;
            var transparency = color == 3 ? new byte[] { 255, 50 } : color == 0 ? new byte[] { 0, 200 } : null;
            document = Fixture();
            document.PdfVersion = "1.3";
            id = PdfImageEditor.InsertImage(document, 1, Png(2, 1, color, samples, 0, palette, transparency), 0, 0, 2, 1);
            image = document.Objects.Single(o => o.Id == id).Value;
            var mask = new PdfGraph(document).Resolve(image.Entries!["SMask"]);
            Check(Inflate(mask).SequenceEqual(new byte[] { 255, color == 0 ? (byte)0 : (byte)50 }), "PNG alpha " + color);
            Check(Inflate(image).SequenceEqual(color is 0 or 4 ? new byte[] { 0, 200 } : new byte[] { 255, 0, 0, 0, 0, 255 }), "PNG pixels " + color);
            Check(document.PdfVersion == "1.4", "soft mask requires PDF 1.4");
        }

        document = Fixture();
        var blankPage = new PdfGraph(document).Pages()[1].Dictionary;
        blankPage.Entries!.Remove("Contents");
        document.TextIndex.Clear();
        PdfImageEditor.InsertImage(document, 2, jpeg, 0, 0, 10, 10);
        Check(document.ImageIndex[1].Images.Count == 1 && document.TextIndex[1].Text == "", "page without Contents");

        void Reject(Action action, string name)
        {
            var before = PdfConverter.ToJson(document);
            try
            {
                action();
            }
            catch (Exception ex) when (ex is ArgumentException or InvalidDataException or NotSupportedException)
            {
                Check(PdfConverter.ToJson(document) == before, "atomic failure: " + name);
                return;
            }

            throw new Exception("Image insertion accepted " + name);
        }

        Reject(() => PdfImageEditor.InsertImage(document, 0, jpeg, 0, 0, 1, 1), "invalid page");
        Reject(() => PdfImageEditor.InsertImage(document, 1, jpeg, 0, 0, 0, 1), "zero width");
        Reject(() => PdfImageEditor.InsertImage(document, 1, jpeg, double.NaN, 0, 1, 1), "nonfinite coordinate");
        Reject(() => PdfImageEditor.InsertImage(document, 1, [1, 2, 3], 0, 0, 1, 1), "unknown format");
        Reject(() => PdfImageEditor.InsertImage(document, 1, jpeg[..20], 0, 0, 1, 1), "truncated JPEG");
        var badPng = Png(1, 1, 2, [255, 0, 0], 0);
        badPng[^1] ^= 1;
        Reject(() => PdfImageEditor.InsertImage(document, 1, badPng, 0, 0, 1, 1), "PNG checksum");
        Reject(() => PdfImageEditor.InsertImage(document, 1, Png(1, 1, 2, [0], 0), 0, 0, 1, 1), "PNG sample count");
        var targetStream = new PdfGraph(document).Pages()[0].Streams.Single().Value;
        targetStream.Base64 = Convert.ToBase64String("q\n"u8);
        document.TextIndex.Clear();
        Reject(() => PdfImageEditor.InsertImage(document, 1, jpeg, 0, 0, 1, 1), "unbalanced original content");
        Console.WriteLine($"Passed {checks} image insertion checks.");
    }

    private static byte[] Inflate(PdfValue image)
    {
        using var input = new MemoryStream(Convert.FromBase64String(image.Base64!));
        using var zip = new ZLibStream(input, CompressionMode.Decompress);
        using var output = new MemoryStream();
        zip.CopyTo(output);
        return output.ToArray();
    }

    private static byte[] Png(int width, int height, byte color, byte[] samples, byte filter, byte[]? palette = null, byte[]? transparency = null, byte bitDepth = 8)
    {
        using var file = new MemoryStream();
        file.Write(new byte[] { 137, 80, 78, 71, 13, 10, 26, 10 });
        void Chunk(string name, byte[] data)
        {
            var length = new byte[4];
            BinaryPrimitives.WriteInt32BigEndian(length, data.Length);
            file.Write(length);
            var body = Encoding.ASCII.GetBytes(name).Concat(data).ToArray();
            file.Write(body);
            var crc = uint.MaxValue;
            foreach (var value in body)
            {
                crc ^= value;
                for (var bit = 0; bit < 8; bit++)
                {
                    crc = (crc & 1) != 0 ? (crc >> 1) ^ 0xEDB88320u : crc >> 1;
                }
            }

            BinaryPrimitives.WriteUInt32BigEndian(length, ~crc);
            file.Write(length);
        }

        var header = new byte[13];
        BinaryPrimitives.WriteInt32BigEndian(header, width);
        BinaryPrimitives.WriteInt32BigEndian(header.AsSpan(4), height);
        header[8] = bitDepth;
        header[9] = color;
        Chunk("IHDR", header);
        if (palette is not null)
        {
            Chunk("PLTE", palette);
        }

        if (transparency is not null)
        {
            Chunk("tRNS", transparency);
        }

        using var compressed = new MemoryStream();
        using (var zip = new ZLibStream(compressed, CompressionLevel.Optimal, true))
        {
            var components = color switch { 0 or 3 => 1, 2 => 3, 4 => 2, _ => 4 };
            var rowLength = (width * components * bitDepth + 7) / 8;
            for (var row = 0; row < height; row++)
            {
                zip.WriteByte(filter);
                for (var col = 0; col < rowLength && row * rowLength + col < samples.Length; col++)
                {
                    var offset = row * rowLength + col;
                    var left = col >= components ? samples[offset - components] : 0;
                    var up = row > 0 ? samples[offset - rowLength] : 0;
                    var corner = row > 0 && col >= components ? samples[offset - rowLength - components] : 0;
                    var p = left + up - corner;
                    var pa = Math.Abs(p - left);
                    var pb = Math.Abs(p - up);
                    var pc = Math.Abs(p - corner);
                    var prediction = filter switch { 0 => 0, 1 => left, 2 => up, 3 => (left + up) / 2, _ => pa <= pb && pa <= pc ? left : pb <= pc ? up : corner };
                    zip.WriteByte(unchecked((byte)(samples[offset] - prediction)));
                }
            }
        }

        Chunk("IDAT", compressed.ToArray());
        Chunk("IEND", []);
        return file.ToArray();
    }
}
